#include <list>
#include <algorithm>

int main() {
    std::list<int> l1 = {1, 2, 3};
    std::list<int> l2 = {4, 5};

    // Guaranteed no-throw operation (internal pointer manipulation)
    l1.reverse(); 

    // Guaranteed no-throw operation (assuming standard allocator/comparison)
    l1.swap(l2);

    // Guaranteed no-throw operation (if default comparison doesn't throw)
    l1.merge(l2);

    // l2 is now empty, l1 contains {5, 4, 3, 2, 1} (or similar, depending on merge sort)
    return 0;
}
